class Solution {
  public String findContestMatch(int n) {
    String[] teams = new String[n];
    for (int i = 0; i < n; i++) teams[i] = String.valueOf(i + 1);
    for (int size = n; size > 1; size /= 2)
      for (int i = 0; i < size / 2; i++) teams[i] = "(" + teams[i] + "," + teams[size - 1 - i] + ")";
    return teams[0];
  }
}
